create extension if not exists "uuid-ossp";
create table plans (id uuid primary key default uuid_generate_v4(), name text not null, description text, duration_days int not null, price numeric not null, is_active boolean default true, created_at timestamp default now(), updated_at timestamp default now(), type text check (type in ('Mensual','Trimestral','Semestral','Anual','Visita','Promoción')));
create table users (id uuid primary key default uuid_generate_v4(), member_number text not null, name text not null, email text not null, status text not null default 'Activo' check (status in ('Activo','Inactivo','Suspendido')), plan text, start_date timestamp not null default now(), next_payment timestamp, plan_id uuid references plans(id), is_free_user boolean default false, paid_until date, updated_at timestamp default now());
create table payments (id uuid primary key default uuid_generate_v4(), user_id uuid references users(id) on delete cascade, amount numeric not null, date timestamp not null default now(), next_payment timestamp not null, status text not null default 'Pendiente' check (status in ('Pagado','Pendiente','Vencido')), method text not null check (method in ('Efectivo','Transferencia','Tarjeta')), created_at timestamp default now());
create table invoices (id uuid primary key default uuid_generate_v4(), user_id uuid references users(id) on delete cascade, plan_id uuid references plans(id) on delete set null, invoice_number text not null unique, amount numeric not null, due_date timestamp not null, paid_at timestamp, status text not null default 'Pendiente' check (status in ('Pendiente','Pagada','Vencida')), method text check (method in ('Efectivo','Transferencia','Tarjeta','Pago Móvil')), reference text, notes text, created_at timestamp default now(), concept text);
create unique index idx_invoices_unique_user_plan_due on invoices(user_id, plan_id, due_date) where status in ('Pendiente','Pagada');
create sequence invoice_number_seq;
create function generate_invoice_number() returns text language plpgsql security definer as $$ begin return 'FAC-'||to_char(now(),'YYYY')||'-'||lpad(nextval('invoice_number_seq')::text,4,'0'); end $$;
